+import { promises as fs } from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import { buildSite } from '../src';
+
+describe('buildSite', () => {
+  let root: string;
+
+  beforeEach(async () => {
+    root = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-'));
+  });
+
+  afterEach(async () => {
+    await fs.rm(root, { recursive: true, force: true });
+  });
+
+  test('renders frontmatter, Markdown, and an index', async () => {
+    const content = path.join(root, 'content');
+    const output = path.join(root, 'public');
+    await fs.mkdir(content);
+    await fs.writeFile(path.join(content, 'hello.md'), `---
+title: Hello World
+date: 2024-01-02
+tags: [news, welcome]
+---
+This is **important**.
+`);
+
+    const pages = await buildSite({ contentDir: content, outputDir: output });
+    const page = await fs.readFile(path.join(output, 'hello.html'), 'utf8');
+    const index = await fs.readFile(path.join(output, 'index.html'), 'utf8');
+
+    expect(pages).toEqual([expect.objectContaining({
+      title: 'Hello World',
+      date: '2024-01-02',
+      tags: ['news', 'welcome'],
+      url: 'hello.html',
+    })]);
+    expect(page).toContain('<strong>important</strong>');
+    expect(page).toContain('<title>Hello World</title>');
+    expect(page).toContain('Tags: news, welcome');
+    expect(index).toContain('<a href="hello.html">Hello World</a>');
+  });
+
+  test('supports nested pages, title fallback, and cleans stale output', async () => {
+    const content = path.join(root, 'articles');
+    const output = path.join(root, 'site');
+    await fs.mkdir(path.join(content, 'guides'), { recursive: true });
+    await fs.mkdir(output);
+    await fs.writeFile(path.join(content, 'guides', 'start.md'), '# Start');
+    await fs.writeFile(path.join(content, 'ignore.txt'), 'not a page');
+    await fs.writeFile(path.join(output, 'stale.html'), 'old');
+
+    const pages = await buildSite({ contentDir: content, outputDir: output });
+
+    expect(pages).toHaveLength(1);
+    expect(pages[0]).toEqual(expect.objectContaining({ title: 'start', url: 'guides/start.html' }));
+    await expect(fs.readFile(path.join(output, 'guides', 'start.html'), 'utf8')).resolves.toContain('<h1>Start</h1>');
+    await expect(fs.stat(path.join(output, 'stale.html'))).rejects.toMatchObject({ code: 'ENOENT' });
+  });
+
+  test('escapes frontmatter inserted into HTML', async () => {
+    const content = path.join(root, 'content');
+    const output = path.join(root, 'dist');
+    await fs.mkdir(content);
+    await fs.writeFile(path.join(content, 'safe.md'), '---\ntitle: "<script>alert(1)</script>"\n---\nText');
+
+    await buildSite({ contentDir: content, outputDir: output });
+    const page = await fs.readFile(path.join(output, 'safe.html'), 'utf8');
+
+    expect(page).not.toContain('<script>');
+    expect(page).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
+  });
+});
*** Add File: tests/cli.test.ts
+import { promises as fs } from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+import { run } from '../src/cli';
+
+describe('CLI', () => {
+  test('build accepts custom content and output directories', async () => {
+    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-cli-'));
+    const content = path.join(root, 'posts');
+    const output = path.join(root, 'web');
+    const stdout = jest.spyOn(process.stdout, 'write').mockImplementation(() => true);
+    await fs.mkdir(content);
+    await fs.writeFile(path.join(content, 'post.md'), 'A post');
+
+    try {
+      await run(['build', '--content', content, '--output', output]);
+      await expect(fs.readFile(path.join(output, 'post.html'), 'utf8')).resolves.toContain('<p>A post</p>');
+      expect(stdout).toHaveBeenCalledWith('Generated 1 page.\n');
+    } finally {
+      stdout.mockRestore();
+      await fs.rm(root, { recursive: true, force: true });
+    }
+  });
+
+  test('rejects unsupported commands and invalid options', async () => {
+    await expect(run([])).rejects.toThrow('Usage: ssg build');
+    await expect(run(['serve'])).rejects.toThrow('Usage: ssg build');
+    await expect(run(['build', '--content'])).rejects.toThrow('Missing value for --content');
+    await expect(run(['build', '--port', '80'])).rejects.toThrow('Unknown option: --port');
+  });
+});
*** Add File: README.md
+# ssg
+
+A strict TypeScript CLI that turns Markdown files into a static HTML site. Frontmatter supports `title`, `date`, and `tags`.
+
+## Usage
+
+```sh
+npm install
+npm run build
+npx ssg build
+```
+
+The default input directory is `./content` and the default output directory is `./dist`.
+
+```sh
+npx ssg build --content ./posts --output ./public
+```
+
+Markdown files in nested directories retain their relative paths. Every page is linked from the generated `index.html`.
+
+This tool has no HTTP API or REST endpoints. It only reads local Markdown and writes static files, so no network API protocol is involved.
*** End Patch

