+    await fs.mkdir(output);
+    await fs.writeFile(path.join(content, 'guides', 'start.md'), '# Start');
+    await fs.writeFile(path.join(content, 'ignore.txt'), 'not a page');
+    await fs.writeFile(path.join(output, 'stale.html'), 'old');
